"""Advanced SteelIndustry questions that must use the LLM planning path."""


def llm_q(case_id, category, intent, question, sql, columns, ordered=False):
    return {
        "id": case_id,
        "profile": "steel_industry",
        "category": category,
        "tags": ["agent_challenge", "llm_required"],
        "expected_intent": intent,
        "turns": [{
            "question": question,
            "gold_sql": sql,
            "expected_status": "success",
            "expected_columns": columns,
            "ordered": ordered,
            "required_nodes": ["generate_structured_query_spec"],
        }],
    }


