    llm_q("steel_agent_005", "statistical_analysis", "aggregate", "按负荷类型计算耗电量与二氧化碳排放的皮尔逊相关系数。", "SELECT ltd.load_type_name, (COUNT(*) * SUM(er.usage_kwh * er.co2_tco2) - SUM(er.usage_kwh) * SUM(er.co2_tco2)) / NULLIF(SQRT((COUNT(*) * SUM(er.usage_kwh * er.usage_kwh) - POW(SUM(er.usage_kwh), 2)) * (COUNT(*) * SUM(er.co2_tco2 * er.co2_tco2) - POW(SUM(er.co2_tco2), 2))), 0) AS correlation_coefficient FROM energy_readings er JOIN load_type_dim ltd ON ltd.load_type_id = er.load_type_id GROUP BY ltd.load_type_name ORDER BY ltd.load_type_name", ["load_type_name", "correlation_coefficient"], True),
    llm_q("steel_agent_006", "statistical_analysis", "lookup", "找出功率因数低于各负荷类型平均值一个标准差的异常读数，返回读数编号、负荷类型和功率因数。", "SELECT er.reading_id, ltd.load_type_name, er.power_factor FROM energy_readings er JOIN load_type_dim ltd ON ltd.load_type_id = er.load_type_id JOIN (SELECT load_type_id, AVG(power_factor) AS average_power_factor, STDDEV_SAMP(power_factor) AS stddev_power_factor FROM energy_readings GROUP BY load_type_id) stats ON stats.load_type_id = er.load_type_id WHERE er.power_factor < stats.average_power_factor - stats.stddev_power_factor ORDER BY er.reading_id", ["reading_id", "load_type_name", "power_factor"], True),
    llm_q("steel_agent_007", "window_ranking", "topk", "分别统计工作日和周末中每种负荷类型耗电量最高的3条记录。", "WITH ranked AS (SELECT cd.week_status, ltd.load_type_name, er.reading_id, er.usage_kwh, ROW_NUMBER() OVER (PARTITION BY cd.week_status, er.load_type_id ORDER BY er.usage_kwh DESC, er.reading_id) AS row_num FROM energy_readings er JOIN calendar_dim cd ON cd.calendar_id = er.calendar_id JOIN load_type_dim ltd ON ltd.load_type_id = er.load_type_id) SELECT week_status, load_type_name, reading_id, usage_kwh FROM ranked WHERE row_num <= 3 ORDER BY week_status, load_type_name, usage_kwh DESC, reading_id", ["week_status", "load_type_name", "reading_id", "usage_kwh"], True),
