    llm_q("steel_agent_009", "window_sequence", "time_filter", "找出连续3个小时平均耗电量持续上升的起始小时。", "WITH hourly AS (SELECT cd.hour, AVG(er.usage_kwh) AS average_usage_kwh FROM energy_readings er JOIN calendar_dim cd ON cd.calendar_id = er.calendar_id GROUP BY cd.hour), sequenced AS (SELECT hour, average_usage_kwh, LAG(average_usage_kwh, 1) OVER (ORDER BY hour) AS previous_usage_kwh, LAG(average_usage_kwh, 2) OVER (ORDER BY hour) AS two_hours_ago_usage_kwh FROM hourly) SELECT hour - 2 AS start_hour FROM sequenced WHERE average_usage_kwh > previous_usage_kwh AND previous_usage_kwh > two_hours_ago_usage_kwh ORDER BY start_hour", ["start_hour"], True),
